#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_N 20000
#define MAX_LEN 10
#define MAX_SUBSTRINGS 55

typedef struct {
    uint64_t key;
    char text[MAX_LEN + 1];
} Entry;

static uint64_t encode_char(char c) {
    if (c >= '0' && c <= '9')
        return (uint64_t)(c - '0');
    return (uint64_t)(c - 'a' + 10);
}

static uint64_t encode_string(const char *s) {
    uint64_t key = 36;
    while (*s)
        key = key * 37 + encode_char(*s++);
    return key;
}

static int compare_entries(const void *a, const void *b) {
    const Entry *x = (const Entry *)a;
    const Entry *y = (const Entry *)b;
    return (x->key > y->key) - (x->key < y->key);
}

static int compare_keys(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    return (x > y) - (x < y);
}

static int find_key(const uint64_t *keys, int n, uint64_t target) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (keys[mid] < target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return (lo < n && keys[lo] == target) ? lo : -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1)
        return 0;

    Entry entries[MAX_N];
    for (int i = 0; i < n; i++) {
        scanf("%10s", entries[i].text);
        entries[i].key = encode_string(entries[i].text);
    }

    qsort(entries, n, sizeof(Entry), compare_entries);

    uint64_t unique_keys[MAX_N];
    char unique_text[MAX_N][MAX_LEN + 1];
    int frequency[MAX_N];
    int unique_count = 0;

    for (int i = 0; i < n;) {
        int j = i + 1;
        while (j < n && entries[j].key == entries[i].key)
            j++;

        unique_keys[unique_count] = entries[i].key;
        strcpy(unique_text[unique_count], entries[i].text);
        frequency[unique_count] = j - i;
        unique_count++;

        i = j;
    }

    long long answer = 0;

    for (int i = 0; i < unique_count; i++) {
        const char *s = unique_text[i];
        int len = (int)strlen(s);
        uint64_t substrings[MAX_SUBSTRINGS];
        int count = 0;

        for (int start = 0; start < len; start++) {
            uint64_t key = 36;
            for (int end = start; end < len; end++) {
                key = key * 37 + encode_char(s[end]);
                substrings[count++] = key;
            }
        }

        qsort(substrings, count, sizeof(uint64_t), compare_keys);

        long long matching_users = 0;
        for (int j = 0; j < count; j++) {
            if (j > 0 && substrings[j] == substrings[j - 1])
                continue;

            int index = find_key(unique_keys, unique_count, substrings[j]);
            if (index >= 0)
                matching_users += frequency[index];
        }

        answer += (long long)frequency[i] * (matching_users - 1);
    }

    printf("%lld\n", answer);
    return 0;
}
