#include <stdio.h>
#include <string.h>
#include <stdint.h>

#define NMAX 20000
#define MAX_NODES (NMAX * 10 + 1)
#define ALPHABET 36

typedef struct {
    int child[ALPHABET];
    int terminal;
} TrieNode;

static TrieNode trie[MAX_NODES];
static char passwords[NMAX][11];
static int node_count;

static int char_value(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return c - 'a' + 10;
}

static int new_node(void) {
    int id = node_count++;
    for (int i = 0; i < ALPHABET; i++) {
        trie[id].child[i] = -1;
    }
    trie[id].terminal = 0;
    return id;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    new_node();

    for (int i = 0; i < n; i++) {
        scanf("%10s", passwords[i]);

        int node = 0;
        for (int j = 0; passwords[i][j] != '\0'; j++) {
            int c = char_value(passwords[i][j]);
            if (trie[node].child[c] == -1) {
                trie[node].child[c] = new_node();
            }
            node = trie[node].child[c];
        }
        trie[node].terminal++;
    }

    long long answer = 0;

    for (int i = 0; i < n; i++) {
        int len = (int)strlen(passwords[i]);
        uint64_t seen[55];
        int seen_count = 0;
        long long matches = 0;

        for (int start = 0; start < len; start++) {
            int node = 0;
            uint64_t code = 1;

            for (int end = start; end < len; end++) {
                int c = char_value(passwords[i][end]);
                node = trie[node].child[c];
                code = code * 36 + (uint64_t)c;

                int already_seen = 0;
                for (int k = 0; k < seen_count; k++) {
                    if (seen[k] == code) {
                        already_seen = 1;
                        break;
                    }
                }

                if (!already_seen) {
                    seen[seen_count++] = code;
                    matches += trie[node].terminal;
                }
            }
        }

        answer += matches - 1;
    }

    printf("%lld\n", answer);
    return 0;
}
